 }finally{db.close()}
});
for(const text of words.ieee754Binary64Bits)test("VDI3805 every persisted numeric domain retains independent raw binary64 word "+text,async()=>{
 const expected=ownedFixture(),word={bits:BigInt(text)};everyWord(expected,word);const db=Database.deserialize(await exportSqliteDatabase(await vdi3805SnapshotToSqliteDatabase(expected)),{safeIntegers:true});try{
  const bytes=Buffer.alloc(8);bytes.writeBigUInt64BE(word.bits);const scalar=bytes.readDoubleBE();let checked=0;for(const suffix of["valve","radiator","pump","heat_generator","geometry","connection","geometry_parameter","curve_unit","curve_point"]){const name="vdi3805_"+suffix,columns=db.query("PRAGMA table_info("+name+")").all() as {name:string}[];for(const column of columns.filter(c=>c.name.endsWith("_ieee754_bits"))){const field=column.name.slice(0,-13),where=suffix==="connection"&&field==="diameter_mm"?" WHERE diameter_present=1":"";for(const row of db.query("SELECT "+field+" AS value,"+column.name+" AS bits FROM "+name+where).all() as {value:number|null;bits:bigint}[]){expect(BigInt.asUintN(64,row.bits)).toBe(word.bits);expect(row.value).toBe(Number.isNaN(scalar)?null:scalar);checked++}}}expect(checked).toBe(42);expect(await vdi3805SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))).toEqual(expected);
 }finally{db.close()}
});
