test("VDI3805 all unsigned64 limit bits survive independent signed SQLite queries",async()=>{for(const text of choices.unsigned64Words){const expected=ownedFixture(),value=BigInt(text);expected.limits={maxFileBytes:value,maxRecords:value,maxFieldLength:value,maxNestingDepth:value};const db=Database.deserialize(await exportSqliteDatabase(await vdi3805SnapshotToSqliteDatabase(expected)),{safeIntegers:true});try{const row=db.query("SELECT max_file_bytes_u64_bits,max_records_u64_bits,max_field_length_u64_bits,max_nesting_depth_u64_bits FROM vdi3805_limits").get() as Record<string,bigint>;for(const word of Object.values(row))expect(BigInt.asUintN(64,word)).toBe(value);expect(await vdi3805SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))).toEqual(expected)}finally{db.close()}}});
