import { parseVdi3805Snapshot, type SheetAttributes, type VdiQuantityKind } from "../../../../🧬️schema/📸️snapshot/🟦️.ts";
import { VDI3805_SQLITE_SCHEMA, vdi3805SnapshotToSqliteDatabase, vdi3805SnapshotFromSqliteDatabase, type Vdi3805SqliteAttributes, type Vdi3805SqliteSnapshot } from "../🟦️.ts";
import {binary64,type Binary64} from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🌱️value/🔢️ieee754/🟦️.ts";
import {exportSqliteDatabase,importSqliteDatabase} from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts";
function floats<T,K extends keyof T>(value:T,keys:readonly K[]):Omit<T,K>&{[P in K]:Binary64}{const result={...value} as Omit<T,K>&{[P in K]:Binary64};for(const key of keys){if(typeof value[key]!=="number")throw Error("neutral numeric field");Object.assign(result,{[key]:binary64(value[key] as number)})}return result}
function attributes(a:SheetAttributes):Vdi3805SqliteAttributes{switch(a.kind){case"valveHeating":return floats(a,["kvsM3S","authorityMin","authorityMax"]);case"radiator":return floats(a,["standardOutputW","heatExponentN","lengthM","heightM","depthM"]);case"pumpHeating":return floats(a,["nominalFlowM3S","nominalHeadM","motorPowerW","hydraulicEfficiency"]);case"heatGenerator":return floats(a,["nominalHeatOutputW","flowTempMaxC","returnTempMinC"]);case"generic":return a}}
function ownedFixture(input:unknown=fixture):Vdi3805SqliteSnapshot{const s=parseVdi3805Snapshot(input);return{...s,catalog:{...s.catalog,products:s.catalog.products.map(p=>({...p,configuration:{...p.configuration,attributes:attributes(p.configuration.attributes)}}))},geometry:Object.fromEntries(Object.entries(s.geometry).map(([key,g])=>[key,{...g,bbox:floats(g.bbox,["minX","minY","minZ","maxX","maxY","maxZ"]),connections:g.connections.map(c=>({...c,position:c.position.map(binary64) as [Binary64,Binary64,Binary64],direction:c.direction.map(binary64) as [Binary64,Binary64,Binary64],diameterMm:c.diameterMm===undefined||c.diameterMm===null?null:binary64(c.diameterMm)})),parameters:Object.fromEntries(Object.entries(g.parameters).map(([key,value])=>[key,binary64(value)]))}])),curves:Object.fromEntries(Object.entries(s.curves).map(([key,c])=>[key,{...c,xUnit:floats(c.xUnit,["siFactor"]),yUnit:floats(c.yUnit,["siFactor"]),points:c.points.map(p=>floats(p,["x","y"]))}])),limits:{maxFileBytes:BigInt(s.limits.maxFileBytes),maxRecords:BigInt(s.limits.maxRecords),maxFieldLength:BigInt(s.limits.maxFieldLength),maxNestingDepth:BigInt(s.limits.maxNestingDepth)}}}
function everyWord(value:unknown,word:Binary64):void{if(value===null||typeof value!=="object")return;for(const[key,child]of Object.entries(value)){if(child!==null&&typeof child==="object"&&"bits"in child)Object.assign(value,{[key]:word});else everyWord(child,word)}}
function nativeWord(value:number):bigint{const bytes=Buffer.alloc(8);bytes.writeDoubleBE(value);return bytes.readBigUInt64BE()}
test("VDI3805 current native parser preserves all complete fields and rejects malformed nested native subjects",()=>{const parsed=parseVdi3805Snapshot(fixture);expect(parsed.limits).toEqual(fixture.limits);expect<unknown>(parsed.curves["任意\u0000"]!.xUnit).toEqual(fixture.curves["任意\u0000"].xUnit);expect(Object.hasOwn(parsed.editionProfile,"__proto__")).toBe(true);expect(parsed.catalog.products[4]!.configuration.attributes).toEqual({kind:"generic",entries:fixture.catalog.products[4]!.configuration.attributes.entries!.map(x=>({...x,unit:x.unit??null}))});for(const index of[0,1,2,3]){const invalid=structuredClone(fixture);invalid.catalog.products[index]!.sheet=65536;expect(()=>parseVdi3805Snapshot(invalid)).toThrow()}const invalid=structuredClone(fixture);invalid.geometry[""]!.connections[0]!.position=[1,2];expect(()=>parseVdi3805Snapshot(invalid)).toThrow()});
test("VDI3805 independent SQLite queries every catalogue variant and applies authoritative domain edits",async()=>{
 const expected=ownedFixture(),database=await vdi3805SnapshotToSqliteDatabase(expected);expect(VDI3805_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../🗄️.sql",import.meta.url)).text());expect(await vdi3805SnapshotFromSqliteDatabase(database)).toEqual(expected);const db=Database.deserialize(await exportSqliteDatabase(database));try{
  expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query("SELECT p.ordinal,c.attribute_kind FROM vdi3805_product p JOIN vdi3805_configuration c ON c.product_id=p.id ORDER BY p.ordinal").all()).toEqual(fixture.catalog.products.map((p,ordinal)=>({ordinal,attribute_kind:p.configuration.attributes.kind})));
  expect(db.query("SELECT p.ordinal,r.family,f.ordinal AS field,f.text FROM vdi3805_product p JOIN vdi3805_record r ON r.product_id=p.id JOIN vdi3805_record_field f ON f.record_id=r.id ORDER BY p.ordinal,r.ordinal,f.ordinal").all()).toEqual(fixture.catalog.products.flatMap((p,ordinal)=>p.records.flatMap(r=>r.fields.map((text,field)=>({ordinal,family:r.family,field,text})))));
  expect(db.query("SELECT ordinal,product_logical_id,sheet,dn FROM vdi3805_index_entry ORDER BY ordinal").all()).toEqual(fixture.index.entries.map((x,ordinal)=>({ordinal,product_logical_id:x.productId,sheet:x.sheet,dn:x.dn})));expect(db.query("SELECT axis,quantity_kind,delta FROM vdi3805_curve_unit ORDER BY axis").all()).toEqual([{axis:0,quantity_kind:"length",delta:1},{axis:1,quantity_kind:"thermalConductivity",delta:0}]);
  db.run("UPDATE vdi3805_valve SET kvs_m3_s=0.625,kvs_m3_s_ieee754_bits=?,kvs_m3_s_ieee754_class='finite'",[BigInt.asIntN(64,nativeWord(0.625))]);db.run("UPDATE vdi3805_catalogue_extension SET value=? WHERE map_key=''",["Geändert 世界\u0000"]);db.run("UPDATE vdi3805_curve_unit SET quantity_kind='acceleration',delta=0 WHERE axis=0");db.run("UPDATE vdi3805_index_entry SET product_logical_id='another unresolved' WHERE id=1");const a=expected.catalog.products[0]!.configuration.attributes;if(a.kind!=="valveHeating")throw Error("fixture variant");a.kvsM3S={bits:nativeWord(0.625)};expected.catalog.extensions.fields=Object.fromEntries(Object.entries(expected.catalog.extensions.fields).map(([key,value])=>[key,key===""?"Geändert 世界\u0000":value]));expected.curves["任意\u0000"]!.xUnit.kind="acceleration";expected.curves["任意\u0000"]!.xUnit.delta=false;expected.index.entries[0]!.productId="another unresolved";expect(await vdi3805SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))).toEqual(expected);
 }finally{db.close()}
});
for(const text of words.ieee754Binary64Bits)test("VDI3805 every persisted numeric domain retains independent raw binary64 word "+text,async()=>{
 const expected=ownedFixture(),word={bits:BigInt(text)};everyWord(expected,word);const db=Database.deserialize(await exportSqliteDatabase(await vdi3805SnapshotToSqliteDatabase(expected)),{safeIntegers:true});try{
  const bytes=Buffer.alloc(8);bytes.writeBigUInt64BE(word.bits);const scalar=bytes.readDoubleBE();let checked=0;for(const suffix of["valve","radiator","pump","heat_generator","geometry","connection","geometry_parameter","curve_unit","curve_point"]){const name="vdi3805_"+suffix,columns=db.query("PRAGMA table_info("+name+")").all() as {name:string}[];for(const column of columns.filter(c=>c.name.endsWith("_ieee754_bits"))){const field=column.name.slice(0,-13),where=suffix==="connection"&&field==="diameter_mm"?" WHERE diameter_present=1":"";for(const row of db.query("SELECT "+field+" AS value,"+column.name+" AS bits FROM "+name+where).all() as {value:number|null;bits:bigint}[]){expect(BigInt.asUintN(64,row.bits)).toBe(word.bits);expect(row.value).toBe(Number.isNaN(scalar)?null:scalar);checked++}}}expect(checked).toBe(42);expect(await vdi3805SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))).toEqual(expected);
 }finally{db.close()}
});
test("VDI3805 every quantity kind and edition choice retain exact semantic identity",async()=>{for(const kind of choices.quantityKind){const expected=ownedFixture();expected.curves["任意\u0000"]!.xUnit.kind=kind as VdiQuantityKind;expect(await vdi3805SnapshotFromSqliteDatabase(await importSqliteDatabase(await exportSqliteDatabase(await vdi3805SnapshotToSqliteDatabase(expected))))).toEqual(expected)}for(const choice of choices.edition){const expected=ownedFixture();expected.editionProfile[""]=choice as "legacy"|"current";expect(await vdi3805SnapshotFromSqliteDatabase(await importSqliteDatabase(await exportSqliteDatabase(await vdi3805SnapshotToSqliteDatabase(expected))))).toEqual(expected)}});
test("VDI3805 all unsigned64 limit bits survive independent signed SQLite queries",async()=>{for(const text of choices.unsigned64Words){const expected=ownedFixture(),value=BigInt(text);expected.limits={maxFileBytes:value,maxRecords:value,maxFieldLength:value,maxNestingDepth:value};const db=Database.deserialize(await exportSqliteDatabase(await vdi3805SnapshotToSqliteDatabase(expected)),{safeIntegers:true});try{const row=db.query("SELECT max_file_bytes_u64_bits,max_records_u64_bits,max_field_length_u64_bits,max_nesting_depth_u64_bits FROM vdi3805_limits").get() as Record<string,bigint>;for(const word of Object.values(row))expect(BigInt.asUintN(64,word)).toBe(value);expect(await vdi3805SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))).toEqual(expected)}finally{db.close()}}});
for(const sql of malformed)test("VDI3805 shared independent SQL malformed corpus refuses lost native ownership: "+sql,async()=>{const bytes=await exportSqliteDatabase(await vdi3805SnapshotToSqliteDatabase(ownedFixture()));const db=Database.deserialize(bytes);try{db.run("PRAGMA foreign_keys=OFF");db.run("PRAGMA ignore_check_constraints=ON");db.exec(sql);let refused=false;try{await vdi3805SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))}catch{refused=true}expect(refused,sql).toBe(true)}finally{db.close()}});
